// Aggregates the extracted article text from every fetched page.
// "Fetch Article" returns the raw HTML in json.data; the source URL is paired
// back from the "Code" node by item index (HTTP node v4.2 cannot carry input fields).
let aggregated = "";

let sourceUrls = [];
try {
  sourceUrls = $("Code").all().map(item => item.json.url || null);
} catch (e) {
  sourceUrls = [];
}

const stripHtml = (html) => html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
  .replace(/<!--[\s\S]*?-->/g, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/gi, " ")
  .replace(/&amp;/gi, "&")
  .replace(/&quot;/gi, "\"")
  .replace(/&#39;|&rsquo;|&lsquo;/gi, "'")
  .replace(/&ldquo;|&rdquo;/gi, "\"")
  .replace(/&lt;/gi, "<")
  .replace(/&gt;/gi, ">")
  .replace(/\s+/g, " ")
  .trim();

for (let i = 0; i < items.length; i++) {
  const html = typeof items[i].json.data === "string" ? items[i].json.data : "";
  if (!html) continue; // fetch failed or non-HTML response for this item
  const text = stripHtml(html);
  if (text.length < 200) continue; // page blocked, empty, or an error page
  const url = sourceUrls[i] || "Unknown URL";
  aggregated += `Source URL: ${url}\nExtracted Content:\n${text.slice(0, 8000)}\n\n---\n\n`;
}

aggregated = aggregated.trim();
if (!aggregated) {
  aggregated = "No article content could be extracted from the ranked URLs. Base the report on the search-result summaries and extracted snippets only.";
}

return [
  {
    json: {
      aggregated_text: aggregated
    }
  }
];
